arguments.command:
cat > checkout.mjs <<'E'
// ASSUMPTION (pending product decision): an expired promotion rejects the order.
export class PromotionExpiredError extends Error {
  constructor(code) {
    super(`Promotion ${code} has expired`);
    this.name = 'PromotionExpiredError';
    this.code = 'PROMOTION_EXPIRED';
    this.promotionCode = code;
  }
}

export function priceOrder({ items, promotion }, now = new Date()) {
  const subtotal = items.reduce((s, i) => s + i.price * i.quantity, 0);
  if (!promotion) return { subtotal, discount: 0, total: subtotal };
  if (now > new Date(promotion.expiresAt)) throw new PromotionExpiredError(promotion.code);
  const discount = Math.round(subtotal * promotion.percentOff) / 100;
  return { subtotal, discount, total: subtotal - discount };
}
E
cat > checkout.test.mjs <<'E'
import test from 'node:test';
import assert from 'node:assert/strict';
import { priceOrder, PromotionExpiredError } from './checkout.mjs';

const items = [{ price: 50, quantity: 2 }];
const now = new Date('2026-10-07T00:00:00Z');
const promo = (expiresAt) => ({ code: 'SAVE10', percentOff: 10, expiresAt });

test('no promotion: full price', () => {
  assert.deepEqual(priceOrder({ items }, now), { subtotal: 100, discount: 0, total: 100 });
});
test('valid promotion applies discount', () => {
  assert.equal(priceOrder({ items, promotion: promo('2026-10-08T00:00:00Z') }, now).total, 90);
});
test('promotion valid at exact expiry instant', () => {
  assert.equal(priceOrder({ items, promotion: promo('2026-10-07T00:00:00Z') }, now).total, 90);
});
test('expired promotion rejects order with PROMOTION_EXPIRED', () => {
  assert.throws(
    () => priceOrder({ items, promotion: promo('2026-10-06T23:59:59Z') }, now),
    (e) => e instanceof PromotionExpiredError && e.code === 'PROMOTION_EXPIRED' && e.promotionCode === 'SAVE10',
  );
});
E
node --test 2>&1 | grep -E "^# (pass|fail)"

